        assertEquals("four", nextName(controller), "Loop: " + i);
        assertEquals("after", nextName(controller), "Loop: " + i);
        assertNull(nextName(controller), "Loop: " + i);
    }
    // Should not enter the loop
    jmvars.put("VAR", "LAST");
    for (int i = 1; i <= 3; i++) {
        assertEquals("before", nextName(controller), "Loop: " + i);
        assertEquals("after", nextName(controller), "Loop: " + i);
