    assertEquals("zero", vars.get(VAL_NAME));
    assertEquals("2", vars.get(VAL_NAME_NR));
    assertEquals("zero", vars.get(VAL_NAME + "_1"));
    assertEquals("zero", vars.get(VAL_NAME + "_2"));
