@Test
// Un-comment if you want try running the test multiple times locally:
// @RepeatedTest(value = 10)
void ensure_thread_group_initializes_counter_only_once_for_each_thread() throws JMeterEngineException, ExecutionException, InterruptedException, TimeoutException {
    CollectSamplesListener listener = new CollectSamplesListener();
    HashTree tree = testTree(b -> {
        b.add(TestPlan.class, tp -> {
            b.add(OpenModelThreadGroup.class, tg -> {
                tg.setName("Thread Group");
                // 5 samples within 100ms
                // Then 2 sec pause to let all the threads to finish, especially the ones that start at 99ms
                tg.setScheduleString("rate(50 / sec) random_arrivals(100 ms) pause(2 s)");
                b.add(listener);
                b.add(CounterConfig.class, c -> {
                    c.setVarName("counter");
                    c.setIncrement(1);
                });
                b.add(DebugSampler.class, dbg -> {
                    dbg.setName("${counter}");
                    dbg.setDisplayJMeterProperties(false);
                    dbg.setDisplayJMeterVariables(false);
                    dbg.setDisplaySystemProperties(false);
                });
            });
        });
    });
    StandardJMeterEngine engine = new StandardJMeterEngine();
    engine.configure(tree);
    engine.runTest();
    engine.awaitTermination(Duration.ofSeconds(10));
    // There's no guarantee that threads execute exactly in order, so we sort
    // the labels to avoid test failure in case the thread execute out of order.
    List<String> actual = listener.getEvents().stream().map(e -> e.getResult().getSampleLabel()).sorted().collect(Collectors.toList());
    // Use toString for better error message
    Assertions.assertEquals("0\n1\n2\n3\n4", String.join("\n", actual), "Test should produce 5 iterations, so ${counter} should yield 0..4");
}

@Test
void testTimer1() throws Exception {
    ConstantThroughputTimer timer = new ConstantThroughputTimer();
    // Assume this thread only
    assertEquals(0, timer.getCalcMode());
    // 1 per second
    timer.setThroughput(60.0);
    long start = System.currentTimeMillis();
    // Initialise
    long delay = timer.delay();
    assertEquals(0, delay);
    // The test tries to check if the calculated delay is correct.
    // If the build machine is busy, then the sleep(500) may take longer in
    // which case the calculated delay should be shorter.
    // Since the test aims at 1 per second, the delay should be 1000 - elapsed.
    // The test currently assumes elapsed is 500.
    Thread.sleep(500);
    long elapsed = System.currentTimeMillis() - start;
    // 1 second less what has already elapsed
    long expected = 1000 - elapsed;
    if (expected < 0) {
        expected = 0;
    }
    assertAlmostEquals(expected, timer.delay(), 50);
}

