@Test
public void testTimer1() throws Exception {
    // The case is to produce 2 samples per second, and we specify "test duration to be 5 seconds"
    // It means every 5 seconds the sampler must produce 2*5=10 samples
    // However, we generate 31 samples (to ensure generator overflows properly)
    final int throughput = 2;
    final int duration = 5;
    final long seed = 42L;
    final int batchSize = 1;
    ConstantPoissonProcessGenerator gen = getConstantPoissonProcessGenerator(throughput, duration, seed, batchSize);
    gen.generateNext();
    double[] expected = new double[] { 1.3787403472085118, 1.3853924503706834, 1.5435972766632988, 1.8439145670565282, 2.3182678790457665, 3.327744758972868, 3.416117358799227, 3.6378184001643405, 3.914508893950179, 4.516861323360891, // ^^ 10 samples for 5 seconds
    5.861089688439262, 5.886892389546892, 6.04883784433166, 6.932834371796743, 7.182454872116432, 7.937136908931478, 7.9717495544484205, 8.749530906277236, 9.129829359439105, 9.596638914343584, // ^^ 10 samples for the next 5 seconds
    10.157091194132905, 11.789599597385642, 12.088437733764593, 12.855201742074335, 12.900124422510304, 13.567031289116144, 13.7564020338373, 13.762549742953254, 14.088984654178198, 14.870178407479408, // ^^ 10 samples for the next 5 seconds
    16.45828248705902 // ^^ it should exceed 15
    };
    double[] actual = new double[expected.length];
    boolean ok = true;
    for (int i = 0; i < actual.length; i++) {
        actual[i] = gen.next();
        ok = ok && Math.abs(actual[i] - expected[i]) < 0.01;
    }
    if (!ok) {
        assertEquals(Arrays.toString(expected), Arrays.toString(actual), "Schedule does not match expectation, " + "throughput=" + throughput + ", duration=" + duration + "seed=" + seed + ", batchSize=" + batchSize);
    }
}

