@Test
public void testSampleNameMatching() {
    /* matching pairs :
         * sample(\d+) sample2
         * sample(\d+) sample12
         * scenar01-12 scenar01-12
         * samples12 samples12
         * */
    String[] sampleNames = { "sample2", "sample12", "scenar01-12", "samples12" };
    Map<String, Long[]> apdex = ReportGeneratorConfiguration.getApdexPerTransactionParts(apdexString);
    for (String sampleName : sampleNames) {
        boolean hasMatched = false;
        for (Map.Entry<String, Long[]> entry : apdex.entrySet()) {
            if (USE_JAVA_REGEX) {
                Pattern pattern = JMeterUtils.compilePattern(entry.getKey());
                Matcher matcher = pattern.matcher(sampleName);
                if (matcher.matches()) {
                    hasMatched = true;
                }
            } else {
                org.apache.oro.text.regex.Pattern regex = JMeterUtils.getPatternCache().getPattern(entry.getKey());
                PatternMatcher matcher = JMeterUtils.getMatcher();
                if (matcher.matches(sampleName, regex)) {
                    hasMatched = true;
                }
            }
        }
        Assertions.assertTrue(hasMatched);
    }
}

@Test
public void testGetErrorKey() {
    SampleMetadata metadata = new SampleMetadata(',', new String[] { CSVSaveService.SUCCESSFUL, CSVSaveService.RESPONSE_CODE, CSVSaveService.RESPONSE_MESSAGE, CSVSaveService.FAILURE_MESSAGE });
    Sample sample = new Sample(0, metadata, new String[] { "false", "", "", "FailureMessage" });
    assertEquals("FailureMessage", ErrorsSummaryConsumer.getErrorKey(sample));
    sample = new Sample(0, metadata, new String[] { "false", "200", "", "FailureMessage" });
    assertEquals("FailureMessage", ErrorsSummaryConsumer.getErrorKey(sample));
    sample = new Sample(0, metadata, new String[] { "false", "200", "", "" });
    assertEquals(MetricUtils.ASSERTION_FAILED, ErrorsSummaryConsumer.getErrorKey(sample));
    sample = new Sample(0, metadata, new String[] { "false", "200", "", "Test failed: text expected to contain /<title>Some html text</title>/" });
    assertEquals("Test failed: text expected to contain /&lt;title&gt;Some html text&lt;/title&gt;/", ErrorsSummaryConsumer.getErrorKey(sample));
    sample = new Sample(0, metadata, new String[] { "false", "200", "", "Test failed: text expected to contain /{\"glossary\": { \"title\": \"example glossary\"}}/" });
    assertEquals("Test failed: text expected to contain /{&quot;glossary&quot;: { &quot;title&quot;: &quot;example glossary&quot;}}/", ErrorsSummaryConsumer.getErrorKey(sample));
    sample = new Sample(0, metadata, new String[] { "true", "200", "", "" });
    assertEquals("", ErrorsSummaryConsumer.getErrorKey(sample));
    sample = new Sample(0, metadata, new String[] { "false", "403", "", "" });
    assertEquals("403", ErrorsSummaryConsumer.getErrorKey(sample));
    sample = new Sample(0, metadata, new String[] { "false", "500", "Server Error", "" });
    assertEquals("500/Server Error", ErrorsSummaryConsumer.getErrorKey(sample));
}

