@ParameterizedTest(name = "{0}, targetHost={1}, sourceIp={2}")
@MethodSource("implementationsAndIps")
public void test(String httpImplementation, String targetHost, InetAddress sourceIp, WireMockServer server, JMeterVariables vars, TestInfo testInfo) {
    configureStubs(server);
    HTTPSamplerBase http = HTTPSamplerFactory.newInstance(httpImplementation);
    vars.put("IP_ADDR", sourceIp.getHostAddress());
    // Typically it is registered with jmeter.properties, however we don't run full JMeter in the test
    HTTPSamplerBase.registerParser("text/html", LagartoBasedHtmlParser.class.getName());
    http.setConnectTimeout("2000");
    http.setResponseTimeout("4000");
    http.setMethod(HTTPConstants.GET);
    // Theoretically it should work, however it practice it fails
    // in case HTTP Client (implementation) resolves localhost as 120.0.0.1 even in case
    // localIp is IPv6
    http.setDomain(targetHost);
    http.setPort(server.port());
    http.setPath("/index.html");
    http.setFollowRedirects(true);
    http.setUseKeepAlive(true);
    http.setProperty(new FunctionProperty(HTTPSamplerBaseSchema.INSTANCE.getIpSource().getName(), new CompoundVariable("${IP_ADDR}")));
    http.setImageParser(true);
    http.setConcurrentDwn(true);
    http.setConcurrentPool("6");
    http.setEmbeddedUrlRE(".*image.*");
    http.setRunningVersion(true);
    SampleResult result = http.sample();
    if (sourceIp instanceof Inet4Address && targetHost.startsWith("[") || sourceIp instanceof Inet6Address && !targetHost.startsWith("[")) {
        // Connection from IPv4 to IPv6 must fail
        // Connection from IPv6 to IPv4 must fail
        if (HTTPSamplerFactory.IMPL_JAVA.equals(httpImplementation)) {
            // Java implementation is known to ignore source IP, so it should connect anyway
            // pass to "successful" assertion below
            Assumptions.assumeFalse(result.getResponseDataAsString().contains("SocketException: Protocol family unavailable"), "Java implementation might throw 'SocketException: Protocol family unavailable'" + " in case it connects from the wrong source IP");
            Assumptions.assumeFalse(result.getResponseDataAsString().contains("BindException: Cannot assign requested address"), "Java implementation might throw 'BindException: Cannot assign requested address'" + " in case it connects from the wrong source IP");
        } else if (result.isSuccessful() || result.isResponseCodeOK() || !(result.getResponseDataAsString().contains("ConnectException") || result.getResponseDataAsString().contains("BindException") || // java.net.NoRouteToHostException: No route to host
        result.getResponseDataAsString().contains("NoRouteToHostException") || result.getResponseDataAsString().contains("SocketException"))) {
            Assertions.fail("IPv4 <-> IPv6 connectivity must fail." + " sourceIp = " + sourceIp + ", targetHost = " + targetHost + " result = " + ResultAsString.toString(result));
        } else {
            return;
        }
    }
    String expected = "url: http://wiremock/index.html\n" + "response: OK\n" + "data.size: 85\n" + "data: <html><body><img src='image1.png'><img src='image2.png'><img src='image3.png'></body>\n" + "- url: http://wiremock/image1.png\n" + "  response: OK\n" + "  data.size: 8\n" + "  data: content1\n" + "- url: http://wiremock/image2.png\n" + "  response: OK\n" + "  data.size: 8\n" + "  data: content2\n" + "- url: http://wiremock/image3.png\n" + "  response: OK\n" + "  data.size: 8\n" + "  data: content3\n" + "- url: http://wiremock/index.html\n" + "  response: OK\n" + "  data.size: 85\n" + "  data: <html><body><img src='image1.png'><img src='image2.png'><img src='image3.png'></body>\n";
    expected = expected.replace("http://wiremock", "http://" + targetHost + ":" + server.port());
    Assertions.assertEquals(expected.replaceAll("\n", System.lineSeparator()), ResultAsString.toString(result), // https://github.com/junit-team/junit5/issues/2041
    testInfo.getDisplayName());
}

